const images = [

  "img_nature.jpg",

  "img_snowtops.jpg",

  "img_mountains.jpg"

];

let index = 0;

let timer;

function showNextSlide() {

  index = (index + 1) % images.length;

  document.getElementById("slide").src = images[index];

}

function startSlides() {

  if (!timer) {

    timer = setInterval(showNextSlide, 3000);

  }

}

function stopSlides() {

  clearInterval(timer);

  timer = undefined;

}
